package renderhost

import (
	"strings"
	"testing"
)

// oldLoreMD is a LORE.md an older lore rendered: its v0.1.17 header and
// one rule, one hotfix and one memory whose rows live in that lore's db.
const oldLoreMD = `<!-- AICODER:CANARY=rnd_1141dffa21f73935 SCHEMA=v1 -->
<!-- This file is generated by lore render. Do not edit by hand. -->

<rule id="rul_019f22dfe48c72bf8fb85d0e251497c9" severity="must" trust="0.50">
Always develop on dev; promote by merge only
</rule>

<hotfix id="hfx_019f322aff377e059d863195e81c3e5b" severity="high">
Flush the cache before the staging deploy
</hotfix>

<memory id="mem_019f322aff377e059d863195e81c3e5c">
The nightly job drains the queue
</memory>
`

// TestOrphanRenderKept (devco:S-1): a committed LORE.md whose entries have
// no row in this repo is an orphan, so render keeps it instead of writing
// an empty file over the team's pinned rules; the line names both ways on.
// One known id (live or deleted here), or an id the new body carries, and
// the render goes on as before.
func TestOrphanRenderKept(t *testing.T) {
	none := func(string) bool { return false }
	o, ok := orphanOf(oldLoreMD, ".lore/LORE.md", "<!-- generated by lore render; budget -->\n", none)
	if !ok {
		t.Fatal("a rendered LORE.md whose rows are all absent here is not kept: render would empty it")
	}
	line := o.line()
	for _, want := range []string{"3 entries (1 hotfix, 1 memory, 1 rule)", "lore migrate run", "git rm .lore/LORE.md", "lore render"} {
		if !strings.Contains(line, want) {
			t.Errorf("the kept-file line misses %q:\n%s", want, line)
		}
	}

	known := func(id string) bool { return id == "hfx_019f322aff377e059d863195e81c3e5b" }
	if _, ok := orphanOf(oldLoreMD, ".lore/LORE.md", "", known); ok {
		t.Error("a LORE.md with one row known here (a deleted hotfix) is kept: render must drop what this repo deleted")
	}
	if _, ok := orphanOf(oldLoreMD, ".lore/LORE.md", `<rule id="rul_019f22dfe48c72bf8fb85d0e251497c9" severity="must">`, none); ok {
		t.Error("a LORE.md whose rule is in the new body is kept")
	}
	if _, ok := orphanOf("# my notes\n"+`<rule id="rul_019f22dfe48c72bf8fb85d0e251497c9">`+"\n", ".lore/LORE.md", "", none); ok {
		t.Error("a file lore did not render counts as a kept render")
	}
	if _, ok := orphanOf("<!-- generated by lore render; budget claude_code 32000 bytes -->\n# empty\n", ".lore/LORE.md", "", none); ok {
		t.Error("a render with no entries is kept: there is nothing to lose")
	}
}
